//! Verve official website — library crate.
//!
//! Pure CSR (client-side rendering): Trunk builds the default `website` bin to
//! WASM, and `#[wasm_bindgen(start)]` in `src/main.rs` mounts [`App`] onto the
//! `<body>`. This lib holds the i18n locale module, the root [`App`] component,
//! and the router.

pub mod consts;
pub mod utils;

pub mod components;
pub mod pages;

// The i18n module (Locale enum, use_i18n, t!, I18nContextProvider, ...) is
// generated by build.rs into OUT_DIR/i18n/mod.rs, which itself declares
// `pub mod i18n`. Including it at the crate root wires it up as `crate::i18n`.
include!(concat!(env!("OUT_DIR"), "/i18n/mod.rs"));

use leptos::prelude::*;
use leptos_meta::*;
use leptos_router::{
    components::{Route, Router, Routes},
    path, StaticSegment,
};

// Bring the generated i18n items into scope.
use crate::i18n::{use_i18n, I18nContextProvider, Locale};

use pages::{Blog, Download, Features, Home, Pricing};
use pages::docs::{CloudDocs, DocsIndex, VerveServer};

/// Stylesheet link, prefixed with the GitHub Pages base path.
fn stylesheet() -> String {
    utils::asset("tailwind.css")
}

/// Favicon link, prefixed with the base path.
fn favicon() -> String {
    utils::asset("icons/verve.png")
}

/// Root component: provides i18n context + metadata + router.
#[component]
pub fn App() -> impl IntoView {
    // Required for <Stylesheet>/<Title>/<Meta> from leptos_meta in CSR.
    provide_meta_context();

    view! {
        <Stylesheet id="tailwind" href=stylesheet() />
        <Link rel="icon" href=favicon() />
        <Title text="Verve — 原生 GPU 加速研发工作台" />
        <Meta
            name="description"
            content="Verve 是基于 Rust + GPUI 构建的原生、GPU 加速研发工作台，集成接口调试、抓包、服务器排查、压测、Mock、笔记、Hosts 与 JSON 等日常开发工具。"
        />

        <I18nContextProvider>
            <DefaultZhCn />
            <Router base="/verve">
                <components::Shell>
                    <Routes fallback=|| view! { <p class="p-8 text-center">"404 — page not found"</p> }>
                        <Route path=StaticSegment("") view=Home />
                        <Route path=StaticSegment("features") view=Features />
                        <Route path=StaticSegment("download") view=Download />
                        <Route path=StaticSegment("pricing") view=Pricing />
                        <Route path=StaticSegment("blog") view=Blog />
                        <Route path=StaticSegment("docs") view=DocsIndex />
                        <Route path=path!("docs/verve-server") view=VerveServer />
                        <Route path=path!("docs/cloud") view=CloudDocs />
                    </Routes>
                </components::Shell>
            </Router>
        </I18nContextProvider>
    }
}

/// Force the default locale to `zh-CN` on the very first visit (when no
/// preference cookie exists yet). After the user toggles language, the choice
/// is persisted by `leptos_i18n` and this no longer overrides it.
///
/// `leptos_i18n` otherwise resolves the initial locale from the browser's
/// `navigator.languages`, which yields English on English-locale browsers.
#[component]
fn DefaultZhCn() -> impl IntoView {
    let i18n = use_i18n();

    // Run once on mount: if no saved preference exists, default to zh-CN.
    Effect::new(move |_| {
        const PREF_KEY: &str = "verve_locale_initialized";
        let no_pref = web_sys::window()
            .and_then(|w| w.local_storage().ok().flatten())
            .map(|ls| ls.get_item(PREF_KEY).ok().flatten().is_none())
            .unwrap_or(true);

        if no_pref && i18n.get_locale() != Locale::zh_CN {
            i18n.set_locale(Locale::zh_CN);
        }
        // Mark as initialized so future loads respect the persisted choice.
        if let Some(ls) = web_sys::window().and_then(|w| w.local_storage().ok().flatten()) {
            let _ = ls.set_item(PREF_KEY, "1");
        }
    });

    ().into_any()
}
